import json
import sys
import urllib.error
import urllib.parse
import urllib.request

BASE = "http://127.0.0.1:8125"


def get_json(path):
    url = BASE + path
    try:
        with urllib.request.urlopen(url, timeout=30) as response:
            status = response.status
            body = response.read()
    except urllib.error.HTTPError as exc:
        detail = exc.read().decode("utf-8", "replace")
        raise RuntimeError(f"GET {url} failed with HTTP {exc.code}: {detail}") from exc
    except urllib.error.URLError as exc:
        raise RuntimeError(f"GET {url} failed: {exc.reason}") from exc
    if not 200 <= status < 300:
        raise RuntimeError(f"GET {url} failed with HTTP {status}")
    try:
        return json.loads(body)
    except (UnicodeDecodeError, json.JSONDecodeError) as exc:
        raise RuntimeError(f"GET {url} returned invalid JSON: {exc}") from exc


try:
    last_data = get_json("/batches/last")
    if not isinstance(last_data, dict) or type(last_data.get("last_seq")) is not int:
        raise RuntimeError("GET /batches/last JSON must contain integer last_seq")
    last_seq = last_data["last_seq"]

    orders_data = get_json("/orders?" + urllib.parse.urlencode({"after": last_seq}))
    if isinstance(orders_data, list):
        orders = orders_data
    elif isinstance(orders_data, dict) and isinstance(orders_data.get("orders"), list):
        orders = orders_data["orders"]
    else:
        raise RuntimeError("GET /orders JSON must be an orders list or contain an orders list")

    if not orders:
        sys.exit(0)

    seqs = []
    order_count = len(orders)
    total_units = 0
    total_revenue_cents = 0
    revenue_by_region_cents = {}

    for index, order in enumerate(orders):
        if not isinstance(order, dict):
            raise RuntimeError(f"order {index} is not an object")
        for field in ("seq", "units", "unit_price_cents"):
            if type(order.get(field)) is not int:
                raise RuntimeError(f"order {index} field {field} must be an integer")
        region = order.get("region")
        if not isinstance(region, str):
            raise RuntimeError(f"order {index} field region must be a string")
        seqs.append(order["seq"])
        units = order["units"]
        revenue = units * order["unit_price_cents"]
        total_units += units
        total_revenue_cents += revenue
        revenue_by_region_cents[region] = revenue_by_region_cents.get(region, 0) + revenue

    batch = {
        "batch_start_seq": min(seqs),
        "batch_end_seq": max(seqs),
        "order_count": order_count,
        "total_units": total_units,
        "total_revenue_cents": total_revenue_cents,
        "revenue_by_region_cents": revenue_by_region_cents,
    }
    payload = json.dumps(batch, separators=(",", ":")).encode("utf-8")
    request = urllib.request.Request(
        BASE + "/batches",
        data=payload,
        headers={"Content-Type": "application/json"},
        method="POST",
    )
    try:
        with urllib.request.urlopen(request, timeout=30) as response:
            status = response.status
            response.read()
    except urllib.error.HTTPError as exc:
        detail = exc.read().decode("utf-8", "replace")
        raise RuntimeError(f"POST {BASE}/batches failed with HTTP {exc.code}: {detail}") from exc
    except urllib.error.URLError as exc:
        raise RuntimeError(f"POST {BASE}/batches failed: {exc.reason}") from exc
    if not 200 <= status < 300:
        raise RuntimeError(f"POST {BASE}/batches failed with HTTP {status}")
except Exception as exc:
    print(f"Order batch processing failed: {exc}", file=sys.stderr)
    sys.exit(1)
PY
